class Solution:
    def largestRectangleArea(self, heights: List[int]) -> int:
        h=heights+[0];stack=[];best=0
        for i,height in enumerate(h):
            while stack and h[stack[-1]]>height:
                bar=h[stack.pop()];left=stack[-1] if stack else -1
                best=max(best,bar*(i-left-1))
            stack.append(i)
        return best

class Solution {
    public int largestRectangleArea(int[] heights){int n=heights.length;int[]h=Arrays.copyOf(heights,n+1);int[]st=new int[n+1];int top=-1,best=0;for(int i=0;i<=n;i++){while(top>=0&&h[st[top]]>h[i]){int bar=h[st[top--]],left=top>=0?st[top]:-1;best=Math.max(best,bar*(i-left-1));}st[++top]=i;}return best;}
}

