from collections import Counter

class Solution:
    def isScramble(self, s1: str, s2: str) -> bool:
        if len(s1)!=len(s2):return False
        @lru_cache(None)
        def dfs(a,b):
            if a==b:return True
            if Counter(a)!=Counter(b):return False
            for i in range(1,len(a)):
                if (dfs(a[:i],b[:i]) and dfs(a[i:],b[i:])) or (dfs(a[:i],b[-i:]) and dfs(a[i:],b[:-i])):return True
            return False
        return dfs(s1,s2)

import java.util.*;

class Solution {
    private Map<String,Boolean> memo;
    public boolean isScramble(String s1,String s2){if(s1.length()!=s2.length())return false;memo=new HashMap<>();return dfs(s1,s2);}
    private boolean dfs(String a,String b){if(a.equals(b))return true;String key=a+"#"+b;if(memo.containsKey(key))return memo.get(key);char[]x=a.toCharArray(),y=b.toCharArray();Arrays.sort(x);Arrays.sort(y);if(!Arrays.equals(x,y)){memo.put(key,false);return false;}for(int i=1;i<a.length();i++){if((dfs(a.substring(0,i),b.substring(0,i))&&dfs(a.substring(i),b.substring(i)))||(dfs(a.substring(0,i),b.substring(b.length()-i))&&dfs(a.substring(i),b.substring(0,b.length()-i)))){memo.put(key,true);return true;}}memo.put(key,false);return false;}
}

