class Solution:
    def reverseBetween(self, head: Optional[ListNode], left: int, right: int) -> Optional[ListNode]:
        dummy=ListNode(0,head);prev=dummy
        for _ in range(left-1):prev=prev.next
        curr=prev.next
        for _ in range(right-left):
            move=curr.next;curr.next=move.next;move.next=prev.next;prev.next=move
        return dummy.next

class Solution {
    public ListNode reverseBetween(ListNode head,int left,int right){ListNode d=new ListNode(0,head),prev=d;for(int i=1;i<left;i++)prev=prev.next;ListNode cur=prev.next;for(int i=0;i<right-left;i++){ListNode move=cur.next;cur.next=move.next;move.next=prev.next;prev.next=move;}return d.next;}
}

