class Solution:
    def restoreIpAddresses(self, s: str) -> List[str]:
        out=[];parts=[]
        def dfs(i):
            if len(parts)==4:
                if i==len(s):out.append('.'.join(parts))
                return
            for length in range(1,4):
                if i+length>len(s):break
                part=s[i:i+length]
                if (length>1 and part[0]=='0') or int(part)>255:continue
                parts.append(part);dfs(i+length);parts.pop()
        if 4<=len(s)<=12:dfs(0)
        return out

import java.util.*;

class Solution {
    public List<String> restoreIpAddresses(String s){List<String>out=new ArrayList<>();if(s.length()>=4&&s.length()<=12)dfs(s,0,new ArrayList<>(),out);return out;}
    private void dfs(String s,int i,List<String>p,List<String>out){if(p.size()==4){if(i==s.length())out.add(String.join(".",p));return;}for(int len=1;len<=3&&i+len<=s.length();len++){String x=s.substring(i,i+len);if((len>1&&x.charAt(0)=='0')||Integer.parseInt(x)>255)continue;p.add(x);dfs(s,i+len,p,out);p.remove(p.size()-1);}}
}

