class Solution:
    def isValidBST(self, root: Optional[TreeNode]) -> bool:
        def valid(node,low,high):
            if not node:return True
            if not low<node.val<high:return False
            return valid(node.left,low,node.val) and valid(node.right,node.val,high)
        return valid(root,float('-inf'),float('inf'))

class Solution {
    public boolean isValidBST(TreeNode root){return valid(root,Long.MIN_VALUE,Long.MAX_VALUE);}
    private boolean valid(TreeNode n,long low,long high){if(n==null)return true;if(n.val<=low||n.val>=high)return false;return valid(n.left,low,n.val)&&valid(n.right,n.val,high);}
}

