class Solution:
    def recoverTree(self, root: Optional[TreeNode]) -> None:
        stack=[];node=root;prev=first=second=None
        while node or stack:
            while node:stack.append(node);node=node.left
            node=stack.pop()
            if prev and prev.val>node.val:
                if first is None:first=prev
                second=node
            prev=node;node=node.right
        first.val,second.val=second.val,first.val

class Solution {
    public void recoverTree(TreeNode root){Deque<TreeNode>st=new ArrayDeque<>();TreeNode node=root,prev=null,first=null,second=null;while(node!=null||!st.isEmpty()){while(node!=null){st.push(node);node=node.left;}node=st.pop();if(prev!=null&&prev.val>node.val){if(first==null)first=prev;second=node;}prev=node;node=node.right;}int t=first.val;first.val=second.val;second.val=t;}
}

